# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: the Variables pane's rows, with no UI code: what the session's Python namespace holds
#          (r1, q1, your own names) as text for a table, one variable's details (how it was
#          made, its columns or repr), and the line about the last clear (Session.clear / restore
#          / purge hold the values themselves).
# Usage: rows(session, show_all) / detail(session, name) / summary(...) / trash_text(session),
#        read by state.py. Requirements: spec/experimental/reflex-kernel/variables.md.
# ---------------------------------------------------------------------------
from __future__ import annotations

import json
import reprlib
from typing import TYPE_CHECKING, Any

import polars as pl

from . import perf
from .session import BUILTIN_NAMES

if TYPE_CHECKING:
    from .session import Session

Row = dict[str, str]

# Names put in the namespace up front (pl, db): never the user's.
SKIP = BUILTIN_NAMES
# How long a cleared batch can be put back; then it is dropped and its memory freed. Undo toasts
# usually stay 5 to 10 s (Gmail's undo send starts at 5, Material's snackbars run 4 to 10); the
# user chose shorter: 10 felt like a lot.
UNDO_SECONDS = 3
MAX_COLUMNS = 40
MAX_REPR_CHARS = 600
MAX_INPUT_CHARS = 600
MAX_NAMES_SHOWN = 6
PYTHON = "python"


def names(session: Session, show_all: bool = False) -> list[str]:
    """The listed variables' names, in the order they were bound."""
    listed = {name for name, _, _ in perf.user_variables(session.namespace, SKIP, show_all)}
    return [name for name in session.namespace if name in listed]


def rows(session: Session, show_all: bool = False) -> list[Row]:
    """One row per variable, in the order bound: name, type, shape, size (and bytes: the same as a
    number, to add up a selection), source (the tool, 'SmashDb
    console', 'cell [3]' or 'python'), tab ('1' when Results can show it), closed ('1' when its tab
    is closed)."""
    found = {name: (value, size) for name, value, size in perf.user_variables(session.namespace, SKIP, show_all)}
    views = session.views()
    return [
        {
            "name": name,
            "type": type(found[name][0]).__name__,
            "shape": perf.shape_text(found[name][0]),
            "size": perf.size_text(found[name][1]),
            "bytes": str(found[name][1]),
            "source": session.sources.get(name, PYTHON),
            "tab": "1" if name in views else "",
            "closed": "1" if name in session.closed else "",
        }
        for name in session.namespace
        if name in found
    ]


def summary(session: Session, show_all: bool = False) -> str:
    """The pane's title line, eg '7 names · 4.2 MB'."""
    found = perf.user_variables(session.namespace, SKIP, show_all)
    if not found:
        return "none yet"
    return f"{len(found)} name{'s' if len(found) != 1 else ''} · {perf.size_text(sum(size for _, _, size in found))}"


def _short(text: str, limit: int) -> str:
    return text if len(text) <= limit else text[:limit] + "…"


def _value_rows(value: Any) -> list[Row]:
    """What a value is, to read: a table's columns and types, else its repr (both capped)."""
    frame = value if isinstance(value, pl.DataFrame) else getattr(value, "df", None)
    if isinstance(frame, pl.DataFrame):
        columns = [f"{name}: {dtype}" for name, dtype in frame.schema.items()]
        more = [f"… {len(columns) - MAX_COLUMNS} more"] if len(columns) > MAX_COLUMNS else []
        return [{"label": "columns", "value": "\n".join(columns[:MAX_COLUMNS] + more)}]
    short = reprlib.Repr()
    short.maxstring = short.maxother = MAX_REPR_CHARS
    try:
        text = short.repr(value)
    except Exception as error:  # noqa: BLE001  # a broken __repr__ must not break the pane
        text = f"<repr failed: {type(error).__name__}>"
    return [{"label": "value", "value": _short(text, MAX_REPR_CHARS)}]


def detail(session: Session, name: str) -> list[Row]:
    """An expanded row, as label / value lines: where it came from, the tool inputs that made it,
    other names bound to the same object, and its columns or repr. [] when the name is gone."""
    if name not in session.namespace:
        return []
    value = session.namespace[name]
    found: list[Row] = [
        {"label": "type", "value": f"{type(value).__module__}.{type(value).__qualname__}"},
        {"label": "from", "value": session.sources.get(name, "python (a cell)")},
    ]
    call = session.calls.get(name)
    if call is not None and call.value is value:
        inputs = json.dumps(call.inputs, default=str, ensure_ascii=False)
        changed = " (changed in its form since the agent's call)" if call.changed else ""
        found.append({"label": "inputs", "value": _short(inputs, MAX_INPUT_CHARS) + changed})
    same = [other for other, held in session.namespace.items() if held is value and other != name and other != "_"]
    if same:
        found.append({"label": "same object as", "value": ", ".join(same) + " (clearing one keeps the data)"})
    return found + _value_rows(value)


def trash_text(session: Session) -> str:
    """The line about the last clear: what is held for Undo, else what the last purge freed, else ''."""
    if session.trash:
        cleared = list(session.trash)
        shown = ", ".join(cleared[:MAX_NAMES_SHOWN])
        more = f" and {len(cleared) - MAX_NAMES_SHOWN} more" if len(cleared) > MAX_NAMES_SHOWN else ""
        size = perf.size_text(sum(item.size for item in session.trash.values()))
        return f"Cleared {shown}{more} ({size})"
    if session.freed_names:
        count = session.freed_names
        return f"freed {perf.size_text(session.freed)}: {count} variable{'s' if count != 1 else ''} cleared for good"
    return ""
